#!/usr/bin/env bash
# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Claude Code hook -- send an Omarchy desktop notification when the AI needs you: a
#          permission prompt, a question / plan to approve, or a finished turn waiting for your
#          next message. For Claude in Zed (its agent loads ~/.claude/settings.json) and in a
#          terminal alike. Zed has no setting for desktop notifications, only its own pop-up.
# Input: hook JSON on stdin (hook_event_name, cwd, tool_name, message). Always exits 0, so a
#        failed notification never blocks the agent.
# Wired up in ~/.claude/settings.json (PermissionRequest, PreToolUse on AskUserQuestion|ExitPlanMode,
#        Notification, Stop); tracked by `os sync`. Needs jq and omarchy-notification-send.
# Rules: a finished turn is not announced while Zed is the focused window (you are looking at
#        it); a second notification within 3 s for the same session is dropped (one prompt can
#        fire two hooks). Clicking the notification focuses Zed when Claude runs inside it.
#
# Example CLI Commands:
#   1. Manual test: echo '{"hook_event_name":"PermissionRequest","tool_name":"Bash","cwd":"'"$PWD"'"}' | .os/scripts/hooks/agent-notify.sh
# ---------------------------------------------------------------------------

ZED_CLASS="dev.zed.Zed"
MIN_GAP_SECONDS=3

input=$(cat)
field() { jq -r "$1 // empty" <<<"$input" 2>/dev/null; }

event=$(field .hook_event_name)
tool=$(field .tool_name)
project=$(basename "$(field .cwd)")
session=$(field .session_id)

in_zed=0
[[ -n ${ZED_ENVIRONMENT:-} || ${CLAUDE_CODE_EXECPATH:-} == */zed/* ]] && in_zed=1

case "$event" in
PermissionRequest) headline="Claude needs permission" detail="${tool:-a tool}" urgency=normal ;;
PreToolUse)
    case "$tool" in
    AskUserQuestion) headline="Claude has a question" detail="" urgency=normal ;;
    ExitPlanMode) headline="Claude has a plan to approve" detail="" urgency=normal ;;
    *) exit 0 ;;
    esac
    ;;
Notification) headline="Claude needs input" detail=$(field .message) urgency=normal ;;
Stop)
    # you are looking at it: no need to say it is done
    if ((in_zed)) && [[ $(hyprctl activewindow -j 2>/dev/null | jq -r '.class // empty') == "$ZED_CLASS" ]]; then
        exit 0
    fi
    headline="Claude is done" detail="waiting for your next message" urgency=low
    ;;
*) exit 0 ;;
esac

# one prompt can fire two hooks (eg PreToolUse and PermissionRequest): keep the first
stamp="${XDG_RUNTIME_DIR:-/tmp}/agent-notify-${session:-none}"
now=$(date +%s)
last=$(cat "$stamp" 2>/dev/null || echo 0)
((now - last < MIN_GAP_SECONDS)) && exit 0
echo "$now" >"$stamp"

description="$project${detail:+ · $detail}"
click=()
((in_zed)) && click=(--exec hyprctl dispatch focuswindow "class:$ZED_CLASS")
omarchy-notification-send --app-name "Claude" -g "󰚩" -u "$urgency" "$headline" "$description" "${click[@]}" \
    >/dev/null 2>&1 || notify-send -u "$urgency" "$headline" "$description" >/dev/null 2>&1
exit 0
